import 'package:flutter/material.dart';
import '../models/item_model.dart';import '../services/firestore_service.dart';import '../utils/app_colors.dart';import '../widgets/item_card.dart';
class HomePage extends StatefulWidget{const HomePage({super.key});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{
 final _service=FirestoreService();final _search=TextEditingController();String _category='Semua';
 @override void dispose(){_search.dispose();super.dispose();}
 @override Widget build(BuildContext context){return Scaffold(backgroundColor:AppColors.background,body:StreamBuilder<List<ItemModel>>(stream:_service.getItems(),builder:(context,s){
 final items=s.data??[];final categoryList=items.map((e)=>e.category).toSet().toList()..sort();final categories=['Semua',...categoryList];
 final visible=items.where((i){final q=_search.text.toLowerCase();final match=i.itemName.toLowerCase().contains(q)||i.code.toLowerCase().contains(q)||i.category.toLowerCase().contains(q);return match&&(_category=='Semua'||i.category==_category);}).toList();
 final available=items.where((e)=>e.status=='Available').length;
 return CustomScrollView(slivers:[
 SliverToBoxAdapter(child:Container(padding:const EdgeInsets.fromLTRB(20,18,20,24),decoration:const BoxDecoration(gradient:LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[AppColors.primary,AppColors.secondary]),borderRadius:BorderRadius.vertical(bottom:Radius.circular(28))),child:SafeArea(bottom:false,child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
 const Text('LABTRACK',style:TextStyle(color:Colors.white70,fontSize:12,fontWeight:FontWeight.bold,letterSpacing:2)),const SizedBox(height:7),const Text('Temukan alat\nyang kamu butuhkan.',style:TextStyle(color:Colors.white,fontSize:25,fontWeight:FontWeight.bold,height:1.2)),const SizedBox(height:18),
 TextField(controller:_search,onChanged:(_)=>setState((){}),decoration:InputDecoration(hintText:'Cari nama, kode, kategori...',prefixIcon:const Icon(Icons.search),filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none))),
 const SizedBox(height:17),Row(children:[_stat('Total barang',items.length.toString(),Icons.inventory_2_outlined),const SizedBox(width:10),_stat('Tersedia',available.toString(),Icons.check_circle_outline)])
 ])))),
 SliverPadding(padding:const EdgeInsets.fromLTRB(18,22,18,0),sliver:SliverToBoxAdapter(child:Row(children:[const Expanded(child:Text('Kategori peralatan',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:AppColors.navy))),Text(categories.length.toString()+' kategori',style:const TextStyle(color:AppColors.muted,fontSize:11))]))),
 SliverToBoxAdapter(child:SizedBox(height:104,child:ListView.separated(padding:const EdgeInsets.fromLTRB(18,13,18,8),scrollDirection:Axis.horizontal,itemCount:categories.length,separatorBuilder:(_,__)=>const SizedBox(width:10),itemBuilder:(context,index){final c=categories[index];final count=c=='Semua'?items.length:items.where((e)=>e.category==c).length;final selected=c==_category;return GestureDetector(onTap:()=>setState(()=>_category=c),child:AnimatedContainer(duration:const Duration(milliseconds:180),width:116,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:selected?AppColors.primary:Colors.white,borderRadius:BorderRadius.circular(17),border:Border.all(color:selected?AppColors.primary:AppColors.border)),child:Column(mainAxisAlignment:MainAxisAlignment.center,crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(_categoryIcon(c),color:selected?Colors.white:AppColors.primary,size:21),const SizedBox(height:6),Text(c,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(fontWeight:FontWeight.bold,fontSize:11,color:selected?Colors.white:AppColors.navy)),Text(count.toString()+' barang',style:TextStyle(fontSize:10,color:selected?Colors.white70:AppColors.muted))])));})))),
 SliverPadding(padding:const EdgeInsets.fromLTRB(18,17,18,8),sliver:SliverToBoxAdapter(child:Row(children:[Expanded(child:Text(_category=='Semua'?'Semua peralatan': 'Peralatan • '+_category,style:const TextStyle(fontSize:18,fontWeight:FontWeight.bold,color:AppColors.navy))),Text(visible.length.toString()+' barang',style:const TextStyle(color:AppColors.muted,fontSize:11))]))),
 if(s.hasError)const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.all(24),child:Text('Gagal memuat data inventaris.')))
 else if(!s.hasData)const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.all(35),child:Center(child:CircularProgressIndicator())))
 else if(visible.isEmpty)const SliverToBoxAdapter(child:Padding(padding:EdgeInsets.all(30),child:Center(child:Text('Belum ada barang pada kategori ini.',style:TextStyle(color:AppColors.muted)))))
 else SliverPadding(padding:const EdgeInsets.fromLTRB(18,5,18,30),sliver:SliverGrid(delegate:SliverChildBuilderDelegate((context,index)=>ItemCard(item:visible[index]),childCount:visible.length),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:220,mainAxisExtent:235,crossAxisSpacing:12,mainAxisSpacing:12))),
 ]);
 }));}
 Widget _stat(String label,String value,IconData icon)=>Expanded(child:Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:Colors.white.withValues(alpha:.17),borderRadius:BorderRadius.circular(15)),child:Row(children:[Icon(icon,color:Colors.white,size:22),const SizedBox(width:10),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(value,style:const TextStyle(color:Colors.white,fontSize:18,fontWeight:FontWeight.bold)),Text(label,style:const TextStyle(color:Colors.white70,fontSize:10))]) ])));
 IconData _categoryIcon(String c){final v=c.toLowerCase();if(v.contains('elektronik'))return Icons.memory;if(v.contains('komponen'))return Icons.developer_board;if(v.contains('optik'))return Icons.biotech;if(v.contains('ukur'))return Icons.straighten;if(v.contains('jaringan'))return Icons.router;if(v.contains('audio'))return Icons.videocam;if(v.contains('perkakas'))return Icons.handyman;return Icons.grid_view;}
}
